# zlib fingerprint: the committed files were produced with a deflate implementation that gives this digest for
# the probe below; on another zlib the byte comparison is skipped and the pixel comparison still applies.
ZLIB_PROBE_SHA256 = "15440594b2eec6e6be132fbb967b53596a40dec644adbf1deb6b879ab780b355"


def _zlib_matches() -> bool:
    probe = bytes(range(256)) * 64 + bytes(i * i % 251 for i in range(5000))
    return hashlib.sha256(zlib.compress(probe, 9)).hexdigest() == ZLIB_PROBE_SHA256


def _sha(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def _generator():
    spec = importlib.util.spec_from_file_location("make_neutral_icons", GENERATOR)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


_BUILT: dict[str, bytes] = {}


def _built() -> dict[str, bytes]:
    if not _BUILT:
        _BUILT.update(_generator().build())
    return _BUILT


def _chunks(png: bytes):
    assert png[:8] == b"\x89PNG\r\n\x1a\n"
    pos = 8
    while pos < len(png):
        n = struct.unpack(">I", png[pos:pos + 4])[0]
        tag, data = png[pos + 4:pos + 8], png[pos + 8:pos + 8 + n]
        assert zlib.crc32(tag + data) & 0xFFFFFFFF == struct.unpack(">I", png[pos + 8 + n:pos + 12 + n])[0], "crc"
        yield tag, data
        pos += 12 + n


def _decode(png: bytes) -> tuple[int, int, bytes]:
    """8-bit RGBA, non-interlaced PNG -> (w, h, rgba), all five filter types."""
    idat, hdr = b"", None
    for tag, data in _chunks(png):
        if tag == b"IHDR":
            hdr = struct.unpack(">IIBBBBB", data)
        elif tag == b"IDAT":
            idat += data
    w, h, depth, colour, _comp, _flt, interlace = hdr
    assert (depth, colour, interlace) == (8, 6, 0)
    raw, stride = zlib.decompress(idat), w * 4
    out, prev = bytearray(), bytes(stride)
    for y in range(h):
        f = raw[y * (stride + 1)]
        row = bytearray(raw[y * (stride + 1) + 1:(y + 1) * (stride + 1)])
        for x in range(stride):
            a = row[x - 4] if x >= 4 else 0
            c = prev[x - 4] if x >= 4 else 0
            up = prev[x]
            if f == 1:
                row[x] = (row[x] + a) & 255
            elif f == 2:
                row[x] = (row[x] + up) & 255
            elif f == 3:
                row[x] = (row[x] + (a + up) // 2) & 255
            elif f == 4:
                p = a + up - c
                pa, pb, pc = abs(p - a), abs(p - up), abs(p - c)
                row[x] = (row[x] + (a if pa <= pb and pa <= pc else up if pb <= pc else c)) & 255
        out += row
        prev = bytes(row)
    return w, h, bytes(out)


def _ico_images(data: bytes) -> list[tuple[int, bytes]]:
    assert struct.unpack("<HHH", data[:6])[:2] == (0, 1)
    out = []
    for i in range(struct.unpack("<H", data[4:6])[0]):
        w, h, _c, _r, _pl, bits, size, off = struct.unpack("<BBBBHHII", data[6 + 16 * i:22 + 16 * i])
        assert (w, bits) == (h, 32)
        out.append((w or 256, data[off:off + size]))
    return out


def _icns_parts(data: bytes) -> list[tuple[str, bytes]]:
    assert data[:4] == b"icns" and struct.unpack(">I", data[4:8])[0] == len(data)
    off, out = 8, []
    while off < len(data):
        tag, n = struct.unpack(">4sI", data[off:off + 8])
        out.append((tag.decode(), data[off + 8:off + n]))
        off += n
    return out


# ---- (a) the files ------------------------------------------------------------------------------------------

def test_the_six_files_exist_and_no_other_asset_sits_in_the_icon_directory():
    assert sorted(p.name for p in ICON_DIR.iterdir() if p.is_file()) == sorted(SIX + ["README.md"])


def test_the_files_differ_from_the_previous_artwork_and_equal_the_generator_output():
    built = _built()
    assert sorted(built) == sorted(SIX)
    for name in SIX:
        data = (ICON_DIR / name).read_bytes()
        assert _sha(data) != OLD_FILES[name], f"{name} is still the previous artwork"
        if name.endswith(".png"):
            assert _decode(data) == _decode(built[name]), f"{name}: pixels differ from the generator output"
    if not _zlib_matches():
        return          # a different deflate implementation: byte equality is not meaningful here
    for name in SIX:
        assert (ICON_DIR / name).read_bytes() == built[name], f"{name} differs from scripts/make_neutral_icons.py output"


def test_the_generator_is_deterministic():
    assert _generator().build() == _built()


def test_png_files_are_rgba_of_the_expected_size_without_metadata():
    for name, n in PNG_SIZES.items():
        data = (ICON_DIR / name).read_bytes()
        w, h, rgba = _decode(data)
        assert (w, h) == (n, n) and len(rgba) == n * n * 4, name
        assert [t for t, _ in _chunks(data)] == [b"IHDR", b"IDAT", b"IEND"], f"{name}: only critical chunks, no metadata"
        assert rgba[3] == 0, f"{name}: the rounded corner is transparent"
        assert rgba[((n // 2) * n + n // 2) * 4 + 3] == 255


def test_ico_holds_every_size_as_png_and_no_metadata():
    data = (ICON_DIR / "icon.ico").read_bytes()
    images = _ico_images(data)
    assert [n for n, _ in images] == ICO_SIZES
    for n, png in images:
        assert _decode(png)[:2] == (n, n)
        assert [t for t, _ in _chunks(png)] == [b"IHDR", b"IDAT", b"IEND"]
    assert len(data) == 6 + 16 * len(images) + sum(len(p) for _, p in images), "nothing else in the file"


def test_icns_holds_the_standard_iconset_sizes_as_png_and_nothing_else():
    data = (ICON_DIR / "icon.icns").read_bytes()
    parts = _icns_parts(data)
    assert sorted(t for t, _ in parts) == sorted(ICNS_TYPES)
    assert len(data) == 8 + sum(8 + len(p) for _, p in parts), "no table of contents, no other element"
    for tag, png in parts:
        assert _decode(png)[:2] == (ICNS_TYPES[tag], ICNS_TYPES[tag]), tag


def test_the_standalone_pngs_are_the_same_images_as_inside_the_icns_and_ico():
    icns = dict(_icns_parts((ICON_DIR / "icon.icns").read_bytes()))
    ico = dict(_ico_images((ICON_DIR / "icon.ico").read_bytes()))
    assert (ICON_DIR / "32x32.png").read_bytes() == icns["icp5"] == ico[32]
    assert (ICON_DIR / "128x128.png").read_bytes() == icns["ic07"] == ico[128]
    assert (ICON_DIR / "128x128@2x.png").read_bytes() == icns["ic08"] == ico[256]
    assert (ICON_DIR / "icon.png").read_bytes() == icns["ic09"]


def test_no_part_of_the_new_files_is_a_part_of_the_previous_artwork():
    parts = [(ICON_DIR / n).read_bytes() for n in SIX]
    parts += [p for _, p in _icns_parts((ICON_DIR / "icon.icns").read_bytes())]
    parts += [p for _, p in _ico_images((ICON_DIR / "icon.ico").read_bytes())]
    for p in parts:
        assert _sha(p) not in OLD_PARTS


def test_macos_iconutil_reads_the_icns_back_when_it_is_available(tmp_path):
    if sys.platform != "darwin" or not shutil.which("iconutil"):
        return
    r = subprocess.run(["iconutil", "-c", "iconset", "-o", str(tmp_path / "x.iconset"), str(ICON_DIR / "icon.icns")],
                       capture_output=True, text=True)
    assert r.returncode == 0, r.stderr
    assert sorted(p.name for p in (tmp_path / "x.iconset").iterdir()) == sorted(
        f"icon_{n}x{n}{s}.png" for n in (16, 32, 128, 256, 512) for s in ("", "@2x"))


# ---- (b) the previous artwork is nowhere in the repository --------------------------------------------------

def _repo_files():
    r = subprocess.run(["git", "-C", str(ROOT), "ls-files", "-z", "--cached", "--others", "--exclude-standard"],
                       capture_output=True)
    if r.returncode == 0 and r.stdout:
        return [ROOT / p.decode() for p in r.stdout.split(b"\0") if p]
    return [p for p in ROOT.rglob("*") if p.is_file() and ".git" not in p.parts]


def test_the_previous_artwork_appears_in_no_file_of_the_repository():
    fingerprints = [bytes.fromhex(fp) for (_n, _l, fp) in OLD_PARTS.values() if fp]
    old_hashes = set(OLD_PARTS) | set(OLD_FILES.values())
    hits = []
    for path in _repo_files():
        if path == THIS_FILE or path.is_symlink() or not path.is_file():
            continue
        data = path.read_bytes()
        if _sha(data) in old_hashes:
            hits.append(f"{path.relative_to(ROOT)}: whole file")
        elif any(fp in data for fp in fingerprints):
            hits.append(f"{path.relative_to(ROOT)}: embeds previous artwork")
    assert not hits, hits


# ---- the bundle configuration and the README ------------------------------------------------------------------

def test_the_bundle_icon_list_still_names_the_five_files_and_all_exist():
    icons = json.loads(CONF.read_text(encoding="utf-8"))["bundle"]["icon"]
    assert icons == ["icons/32x32.png", "icons/128x128.png", "icons/128x128@2x.png", "icons/icon.icns", "icons/icon.ico"]
    for i in icons:
        assert (CONF.parent / i).is_file(), i
    assert (CONF.parent / "icons" / "icon.png").is_file()


def test_readme_marks_the_artwork_temporary_ties_it_to_d_lic_11_and_lists_the_hashes():
    text = README.read_text(encoding="utf-8")
    assert text.isascii()
    assert "TEMPORARY" in text and "D-LIC-11" in text and "scripts/make_neutral_icons.py" in text
    low = text.lower()
    for bad in ("cleared", "compliant", "approved by counsel", "open source", "tamper-proof"):
        assert bad not in low, bad
    listed = dict(re.findall(r"\|\s*`([^`|]+)`\s*\|\s*`([0-9a-f]{64})`\s*\|", text))
    assert sorted(listed) == sorted(SIX)
    for name in SIX:
        assert listed[name] == _sha((ICON_DIR / name).read_bytes()), name
